import { useDeferredValue, useEffect, useRef, useState } from "react";
import { ArrowDown, ArrowUp, ArrowUpRight, Check, ChevronLeft, ChevronRight, Database, Download, Filter, FolderOpen, Search, SlidersHorizontal, X } from "lucide-react";
import { Badge, IconButton, Section, downloadText, type Notice } from "./primitives";
import { references, type Reference } from "./fixtures";

export function DataGallery({ notify }: { notify: Notice }) {
  const [query, setQuery] = useState("");
  const deferredQuery = useDeferredValue(query);
  const [status, setStatus] = useState("All statuses");
  const [order, setOrder] = useState<"name" | "records">("name");
  const [descending, setDescending] = useState(false);
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<string[]>([]);
  const [inspected, setInspected] = useState<Reference>(references[0]);
  const [showGroups, setShowGroups] = useState(true);
  const selectAll = useRef<HTMLInputElement>(null);
  const filtered = references.filter(reference => (!deferredQuery || `${reference.name} ${reference.id} ${reference.owner}`.toLowerCase().includes(deferredQuery.toLowerCase())) && (status === "All statuses" || status === reference.state)).sort((left, right) => (order === "name" ? left.name.localeCompare(right.name) : left.records - right.records) * (descending ? -1 : 1));
  const pageCount = Math.max(1, Math.ceil(filtered.length / 5));
  const visiblePage = Math.min(page, pageCount - 1);
  const visible = filtered.slice(visiblePage * 5, visiblePage * 5 + 5);
  const allChecked = visible.length > 0 && visible.every(reference => selected.includes(reference.id));
  const someChecked = visible.some(reference => selected.includes(reference.id));
  useEffect(() => { if (selectAll.current) selectAll.current.indeterminate = someChecked && !allChecked; }, [someChecked, allChecked]);
  function sortBy(next: typeof order) { setDescending(next === order ? !descending : false); setOrder(next); }
  function exportRows() {
    const rows = selected.length ? references.filter(reference => selected.includes(reference.id)) : filtered;
    const escape = (value: unknown) => `"${String(value).replaceAll('"', '""')}"`;
    downloadText("azure-sky-synthetic-references.csv", ["id,name,group,status,records,date", ...rows.map(reference => [reference.id, reference.name, reference.group, reference.state, reference.records, reference.date].map(escape).join(","))].join("\n"), "text/csv");
    notify(`${rows.length} synthetic references exported`);
  }
  return <Section id="data" index="03" title="Complexity, with a clear view" trailing={<span className="azs-section-tag"><Database size={14} /> Data surfaces</span>}>
    <div className="azs-metric-strip"><div><span className="azs-eyebrow">REFERENCE RECORDS</span><strong>{references.reduce((total, reference) => total + reference.records, 0).toLocaleString("en-US")}</strong><span className="azs-metric-foot"><Database size={13} />Across 12 synthetic collections</span></div><div><span className="azs-eyebrow">REVIEWED COLLECTIONS</span><strong>{references.filter(reference => reference.state === "Reviewed").length}<small>/ 12</small></strong><span className="azs-metric-foot azs-success-text"><Check size={14} />Source review complete</span></div><div><span className="azs-eyebrow">PRECISION SPECIMEN</span><strong>99.982<small>%</small></strong><span className="azs-metric-foot">Fixture value / not a service metric</span></div><div><span className="azs-eyebrow">ARCHIVE COVERAGE</span><strong className="azs-metric-missing">Not available</strong><span className="azs-metric-foot">No coverage fixture</span></div></div>
    <div className="azs-data-layout"><div className="azs-records">
      <div className="azs-table-toolbar"><div className="azs-input-icon"><Search size={16} /><input type="search" placeholder="Search references..." aria-label="Search references" value={query} onChange={event => { setQuery(event.target.value); setPage(0); }} /></div><select aria-label="Filter status" value={status} onChange={event => { setStatus(event.target.value); setPage(0); }}><option>All statuses</option><option>Reviewed</option><option>Needs review</option><option>Pending</option></select><IconButton label="Toggle group column" aria-pressed={showGroups} onClick={() => setShowGroups(value => !value)}><SlidersHorizontal size={17} /></IconButton><button className="azs-button azs-button-secondary" onClick={exportRows}><Download size={15} />Export{selected.length ? ` (${selected.length})` : ""}</button></div>
      {selected.length > 0 && <div className="azs-selection-summary"><Check size={14} /><span>{selected.length} selected</span><button onClick={() => setSelected([])} className="azs-button azs-button-ghost">Clear selection <X size={13} /></button></div>}
      <div className="azs-table-viewport"><table className="azs-table"><caption className="azs-sr-only">Synthetic reference collections</caption><thead><tr><th className="azs-checkbox-cell"><label><input ref={selectAll} type="checkbox" aria-label="Select this page" checked={allChecked} disabled={!visible.length} onChange={() => setSelected(current => allChecked ? current.filter(id => !visible.some(reference => reference.id === id)) : [...new Set([...current, ...visible.map(reference => reference.id)])])} /></label></th><th aria-sort={order === "name" ? descending ? "descending" : "ascending" : "none"}><button onClick={() => sortBy("name")}>Reference{order === "name" && (descending ? <ArrowDown size={13} /> : <ArrowUp size={13} />)}</button></th>{showGroups && <th className="azs-hide-mobile">Group</th>}<th>Status</th><th className="azs-numeric" aria-sort={order === "records" ? descending ? "descending" : "ascending" : "none"}><button onClick={() => sortBy("records")}>Records{order === "records" && (descending ? <ArrowDown size={13} /> : <ArrowUp size={13} />)}</button></th><th className="azs-hide-tablet">Updated</th></tr></thead><tbody>{visible.map(reference => <tr key={reference.id} data-selected={selected.includes(reference.id)} data-inspected={inspected.id === reference.id}><td className="azs-checkbox-cell"><label><input type="checkbox" aria-label={`Select ${reference.name}`} checked={selected.includes(reference.id)} onChange={() => setSelected(current => current.includes(reference.id) ? current.filter(id => id !== reference.id) : [...current, reference.id])} /></label></td><td><button className="azs-record-link" onClick={() => setInspected(reference)} aria-label={`Inspect ${reference.name}`} aria-pressed={inspected.id === reference.id}>{reference.name}<ArrowUpRight size={12} /></button><span className="azs-record-id azs-mono">{reference.id}</span></td>{showGroups && <td className="azs-hide-mobile">{reference.group}</td>}<td><Badge tone={reference.state === "Reviewed" ? "success" : reference.state === "Needs review" ? "warning" : "neutral"}>{reference.state}</Badge></td><td className="azs-numeric azs-mono">{reference.records.toLocaleString("en-US")}</td><td className="azs-hide-tablet azs-mono">{reference.date.slice(5)}</td></tr>)}</tbody></table></div>
      {!filtered.length && <div className="azs-empty"><Search size={30} /><h3>No matching references</h3><p>0 results for "{query}"</p><button className="azs-button azs-button-secondary" onClick={() => { setQuery(""); setStatus("All statuses"); }}>Reset filters</button></div>}
      <div className="azs-pagination"><span className="azs-mono">{filtered.length ? visiblePage * 5 + 1 : 0}-{Math.min((visiblePage + 1) * 5, filtered.length)} of {filtered.length}</span><div className="azs-row"><IconButton label="Previous page" disabled={visiblePage === 0} onClick={() => setPage(value => Math.max(0, value - 1))}><ChevronLeft size={16} /></IconButton><span className="azs-mono">{visiblePage + 1} / {pageCount}</span><IconButton label="Next page" disabled={visiblePage + 1 >= pageCount} onClick={() => setPage(value => value + 1)}><ChevronRight size={16} /></IconButton></div></div>
    </div><aside className="azs-inspector azs-inverse" aria-label="Reference inspector"><div className="azs-row azs-between"><span className="azs-eyebrow">REFERENCE / INSPECTOR</span><FolderOpen size={18} /></div><h3>{inspected.name}</h3><span className="azs-mono">{inspected.id}</span><dl><div><dt>Owner</dt><dd>{inspected.owner}</dd></div><div><dt>Collection</dt><dd>{inspected.group}</dd></div><div><dt>Records</dt><dd className="azs-mono">{inspected.records.toLocaleString("en-US")}</dd></div><div><dt>Updated</dt><dd>{inspected.date}</dd></div><div><dt>Review</dt><dd>{inspected.state}</dd></div></dl><div className="azs-inspector-note"><Filter size={15} /><span>Synthetic specimen<br />No external connection</span></div></aside></div>
  </Section>;
}